const fs = require('fs');
const https = require('https');
const http = require('http');

// Read .env.test file
const envContent = fs.readFileSync('./.env.test', 'utf8');

// Parse environment variables
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
  line = line.trim();
  // Skip empty lines and comments
  if (line && !line.startsWith('#')) {
    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  }
});

console.log('Parsed environment variables:', Object.keys(envVars));

// Prepare JSON payload
const jsonData = JSON.stringify(envVars, null, 2);

// POST to the API endpoint
const url = new URL('http://localhost:47301/api/doc-export');
const options = {
  hostname: url.hostname,
  port: url.port,
  path: url.pathname,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonData)
  }
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`Response status: ${res.statusCode}`);
    console.log('Response body:', data);
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

req.write(jsonData);
req.end();

